const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = '/projects';
const HOST_ROOT = '/mnt/data/projects';
const STATE_FILE = '/memory/project_rag_state.json';

const SKIP_DIRS = new Set(['.git', 'node_modules', 'venv', '.venv', '__pycache__', '.pytest_cache', 'dist', 'build', '.next', 'tmp', 'tmp_staging', 'credentials', 'site-packages', 'dist-packages', '.tox', '.mypy_cache', '.ruff_cache', '.eggs', 'memory']);
const SKIP_DIR_SUFFIXES = ['.egg-info'];
const ALLOWED_EXT = new Set(['.py', '.js', '.jsx', '.ts', '.tsx', '.mjs', '.md', '.mdx', '.txt', '.json', '.yml', '.yaml', '.sh', '.toml', '.cfg', '.ini', '.html', '.css', '.scss', '.sql', '.lark', '.rst']);
const SKIP_FILE_NAMES = new Set(['package-lock.json', 'poetry.lock', 'uv.lock']);

function isSecret(name) {
  if (name === '.env.example') return false;
  if (name === '.env' || name.startsWith('.env.')) return true;
  if (name.endsWith('.pem') || name.endsWith('.key')) return true;
  if (name.startsWith('id_rsa')) return true;
  return false;
}

function isVenvRoot(dir) {
  try { return fs.existsSync(path.join(dir, 'pyvenv.cfg')); } catch (e) { return false; }
}

function walk(dir, acc) {
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return; }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      if (SKIP_DIR_SUFFIXES.some(function (suf) { return entry.name.endsWith(suf); })) continue;
      if (isVenvRoot(full)) continue;
      walk(full, acc);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name).toLowerCase();
      if (!ALLOWED_EXT.has(ext)) continue;
      if (SKIP_FILE_NAMES.has(entry.name)) continue;
      if (isSecret(entry.name)) continue;
      let stat;
      try { stat = fs.statSync(full); } catch (e) { continue; }
      acc.push({ full: full, stat: stat });
    }
  }
}

const files = [];
walk(ROOT, files);

// Load state — handle old format {rel: {hash, mtime}} and new format {files:{...}, dirty_dirs:[...], dirty_projects:[], structure_changed:bool}
let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  if (raw.files !== undefined) {
    state = raw;
  } else {
    state = { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
  }
} catch (e) {
  state = { files: {}, dirty_dirs: [], dirty_projects: [], structure_changed: false };
}

const manifest = state.files || {};
const MAX_NEW_OR_CHANGED_PER_RUN = 15;

const seen = new Set();
const newOrChanged = [];
const dirtyDirs = new Set(state.dirty_dirs || []);
const dirtyProjects = new Set(state.dirty_projects || []);
let structureChanged = state.structure_changed || false;

for (const f of files) {
  const full = f.full;
  const stat = f.stat;
  let content;
  try { content = fs.readFileSync(full, 'utf8'); } catch (e) { continue; }
  if (content.slice(0, 1024).indexOf('\u0000') !== -1) continue;
  if (content.trim().length === 0) continue;

  const rel = path.relative(ROOT, full);
  const hostPath = path.join(HOST_ROOT, rel);
  const relParts = rel.split(path.sep);
  const project = relParts[0];
  const filename = path.basename(full);
  const filetype = path.extname(full).slice(1).toLowerCase();
  const hash = crypto.createHash('sha256').update(content).digest('hex');
  const mtime = stat.mtime.toISOString();

  seen.add(rel);

  const prior = manifest[rel];
  const priorHash = prior ? (prior.content_hash || prior.hash) : null;
  if (priorHash && priorHash === hash) continue;

  // Mark all ancestor directories dirty (deepest propagates upward)
  for (let i = 1; i < relParts.length; i++) {
    dirtyDirs.add(relParts.slice(0, i).join('/'));
  }
  dirtyProjects.add(project);
  if (!prior) structureChanged = true;

  const hierarchyId = relParts.join('/');
  const parentId = relParts.length > 2
    ? relParts.slice(0, -1).join('/')
    : project;

  newOrChanged.push({
    json: {
      status: prior ? 'changed' : 'new',
      rel: rel,
      filepath: hostPath,
      filename: filename,
      filetype: filetype,
      project: project,
      mtime: mtime,
      content_hash: hash,
      content: content,
      hierarchy_id: hierarchyId,
      parent_id: parentId,
    },
  });
}

const output = newOrChanged.slice(0, MAX_NEW_OR_CHANGED_PER_RUN);

for (const rel of Object.keys(manifest)) {
  if (!seen.has(rel)) {
    const relParts = rel.split(path.sep);
    for (let i = 1; i < relParts.length; i++) {
      dirtyDirs.add(relParts.slice(0, i).join('/'));
    }
    dirtyProjects.add(relParts[0]);
    structureChanged = true;
    output.push({
      json: {
        status: 'deleted',
        rel: rel,
        filepath: path.join(HOST_ROOT, rel),
        project: relParts[0],
      },
    });
  }
}

// Write updated dirty state before per-item processing begins
state.dirty_dirs = Array.from(dirtyDirs);
state.dirty_projects = Array.from(dirtyProjects);
state.structure_changed = structureChanged;
fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

return output;

const fs = require('fs');
const STATE_FILE = '/memory/project_rag_state.json';
const rel = $('Walk & Diff').item.json.rel;

let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  state = raw.files !== undefined ? raw : { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
} catch (e) {
  state = { files: {}, dirty_dirs: [], dirty_projects: [], structure_changed: false };
}

delete state.files[rel];
state.structure_changed = true;
fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

return { json: { rel: rel, status: 'removed' } };

const item = $input.item.json;
const content = item.content || '';
const truncated = content.length > 2000 ? content.slice(0, 2000) : content;
const sys = 'You tag project files for a semantic search index. Given a filename and its content, respond with STRICT JSON only (no markdown fences, no commentary): {"chunk_type": "<short label: overview|source_code|config|test|documentation|data|script>", "topics": ["<3-8 short keywords>"], "summary": "<one sentence describing what this file does>", "purpose": "<short phrase: what this file is for>", "responsibilities": ["<verb phrase describing what this file does>"], "dependencies": ["<library, module, or service this file uses>"], "public_apis": ["<exported function/class/constant name>"]}';
const user = 'Project: ' + item.project + '\nFile: ' + item.filename + ' (.' + item.filetype + ')\n\n' + truncated;
return {
  json: {
    model: 'qwen2.5-coder:14b',
    messages: [
      { role: 'system', content: sys },
      { role: 'user', content: user },
    ],
    stream: false,
    options: { temperature: 0.1, num_predict: 400 },
  },
};

const item = $input.item.json;
const requestFailed = !item.message;
const raw = (item.message && item.message.content) || '';
let parsed = {};
if (!requestFailed) {
  try {
    const cleaned = raw.replace(/```json|```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = {};
  }
}
const tagFailed = requestFailed || typeof parsed.chunk_type !== 'string';
if (tagFailed) {
  const fs = require('fs');
  const filepath = $('Walk & Diff').item.json.filepath;
  const reason = requestFailed ? 'ollama_request_failed' : 'unparseable_response';
  const line = new Date().toISOString() + '\t' + reason + '\t' + filepath + '\n';
  try { fs.appendFileSync('/memory/project_rag_failures.log', line); } catch (e) {}
}
return {
  json: {
    chunk_type: typeof parsed.chunk_type === 'string' ? parsed.chunk_type : 'unknown',
    topics: Array.isArray(parsed.topics) ? parsed.topics.filter(function (t) { return typeof t === 'string'; }) : [],
    summary: typeof parsed.summary === 'string' ? parsed.summary : '',
    purpose: typeof parsed.purpose === 'string' ? parsed.purpose : '',
    responsibilities: Array.isArray(parsed.responsibilities) ? parsed.responsibilities : [],
    dependencies: Array.isArray(parsed.dependencies) ? parsed.dependencies : [],
    public_apis: Array.isArray(parsed.public_apis) ? parsed.public_apis : [],
    tag_failed: tagFailed,
  },
};

const crypto = require('crypto');
const http = require('http');

function uuidv5(name) {
  const nsHex = '6ba7b8109dad11d180b400c04fd430c8';
  const nsBuf = Buffer.from(nsHex, 'hex');
  const nameBuf = Buffer.from(name, 'utf8');
  const hash = crypto.createHash('sha1').update(Buffer.concat([nsBuf, nameBuf])).digest();
  hash[6] = (hash[6] & 0x0f) | 0x50;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const h = hash.slice(0, 16).toString('hex');
  return h.slice(0,8) + '-' + h.slice(8,12) + '-' + h.slice(12,16) + '-' + h.slice(16,20) + '-' + h.slice(20,32);
}

function httpCall(method, host, port, urlPath, body) {
  return new Promise(function(resolve, reject) {
    const data = JSON.stringify(body);
    const req = http.request(
      { host: host, port: port, path: urlPath, method: method, headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      function(res) {
        let buf = '';
        res.on('data', function(c) { buf += c; });
        res.on('end', function() { try { resolve(JSON.parse(buf)); } catch(e) { resolve({}); } });
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

const tagItem = $('Parse Tags').item.json;
const walkItem = $('Walk & Diff').item.json;

if (tagItem.tag_failed) {
  return { json: { file_summary_status: 'skipped_tag_failed', hierarchy_id: walkItem.hierarchy_id } };
}

const hierarchyId = walkItem.hierarchy_id;
const parentId = walkItem.parent_id;
const project = walkItem.project;

const embedText = [
  'File: ' + walkItem.filename,
  'Purpose: ' + (tagItem.purpose || tagItem.summary || ''),
  tagItem.responsibilities.length ? 'Responsibilities: ' + tagItem.responsibilities.join(', ') : '',
  tagItem.dependencies.length ? 'Dependencies: ' + tagItem.dependencies.join(', ') : '',
  tagItem.topics.length ? 'Topics: ' + tagItem.topics.join(', ') : '',
].filter(Boolean).join('\n');

const contentText = [
  'Purpose: ' + (tagItem.purpose || tagItem.summary || ''),
  tagItem.responsibilities.length ? 'Responsibilities: ' + tagItem.responsibilities.join(', ') : '',
  tagItem.dependencies.length ? 'Dependencies: ' + tagItem.dependencies.join(', ') : '',
  tagItem.public_apis.length ? 'Public APIs: ' + tagItem.public_apis.join(', ') : '',
  'Topics: ' + tagItem.topics.join(', '),
].filter(Boolean).join('\n');

let vector;
try {
  const embedRes = await httpCall('POST', 'host.docker.internal', 11434, '/api/embed', {
    model: 'qwen3-embedding:4b', input: embedText
  });
  vector = (embedRes.embeddings || [[]])[0];
} catch (e) {
  return { json: { file_summary_status: 'embed_failed', hierarchy_id: hierarchyId, error: String(e) } };
}

if (!vector || !vector.length) {
  return { json: { file_summary_status: 'embed_empty', hierarchy_id: hierarchyId } };
}

const pointId = uuidv5('file:' + hierarchyId);
try {
  await httpCall('PUT', 'qdrant', 6333, '/collections/project_rag/points?wait=false', {
    points: [{
      id: pointId,
      vector: vector,
      payload: {
        content: contentText,
        metadata: {
          hierarchy_id: hierarchyId,
          level: 'file',
          parent_id: parentId,
          project: project,
          filepath: walkItem.filepath,
          filename: walkItem.filename,
          filetype: walkItem.filetype,
          summary: tagItem.summary,
          purpose: tagItem.purpose,
          responsibilities: tagItem.responsibilities,
          dependencies: tagItem.dependencies,
          public_apis: tagItem.public_apis,
          topics: tagItem.topics,
          chunk_type: tagItem.chunk_type,
          content_hash: walkItem.content_hash,
          updated_at: new Date().toISOString()
        }
      }
    }]
  });
} catch (e) {
  return { json: { file_summary_status: 'upsert_failed', hierarchy_id: hierarchyId, error: String(e) } };
}

return { json: { file_summary_status: 'ok', hierarchy_id: hierarchyId, point_id: pointId } };

const fs = require('fs');
const STATE_FILE = '/memory/project_rag_state.json';
const walkItem = $('Walk & Diff').item.json;
const rel = walkItem.rel;
const hash = walkItem.content_hash;
const mtime = walkItem.mtime;
const tagFailed = $('Parse Tags').item.json.tag_failed === true;

if (tagFailed) {
  return { json: { rel: rel, status: 'skipped_tag_failed' } };
}

let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  state = raw.files !== undefined ? raw : { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
} catch (e) {
  state = { files: {}, dirty_dirs: [], dirty_projects: [], structure_changed: false };
}

state.files[rel] = { content_hash: hash, mtime: mtime };
fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

return { json: { rel: rel, status: 'indexed' } };

const fs = require('fs');
const http = require('http');
const STATE_FILE = '/memory/project_rag_state.json';

function fireWebhook(path) {
  return new Promise(function(resolve) {
    const body = '{}';
    const req = http.request(
      { host: 'localhost', port: 5678, path: path, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': 2 } },
      function(res) { resolve(res.statusCode); }
    );
    req.on('error', function() { resolve(null); });
    req.write(body);
    req.end();
  });
}

let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  state = raw.files !== undefined ? raw : { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
} catch (e) {
  state = { files: {}, dirty_dirs: [], dirty_projects: [], structure_changed: false };
}

const results = {
  dirty_dirs: (state.dirty_dirs || []).length,
  structure_changed: state.structure_changed || false,
  triggered_b: false,
  triggered_d: false
};

if ((state.dirty_dirs || []).length > 0) {
  await fireWebhook('/webhook/rag-build-directories');
  results.triggered_b = true;
}

if (state.structure_changed) {
  await fireWebhook('/webhook/rag-build-structure');
  results.triggered_d = true;
}

return [{ json: results }];
